UPDATE ui.emailtemplate SET
subject = '[(${client})] Real Time [(${type})]: [(${alert})] (Account#:[(${accountid})]. Last 4 Digits of Card:[(${lastfourdigit})] Transaction Amount:[(${amount})] - [(${type}  == ''Alert'' ? ''Approved'':''Declined'')])'::text WHERE
id = 2;

UPDATE ui.emailtemplate SET
subject = '[(${client})] Risky Transaction Alert'::text WHERE
id = 1;


UPDATE ui.dashboardresultset SET
vcdashboardresultsetschema = '{
    "Account ID": "integer",
    "Document Number": "string",
    "Last 4 digits of card": "string",
    "Customer Name": "string",
    "Transaction Amount": "float",
    "Authorization Timestamp": "datetime",
    "Advanced Authorization Risk Score": "integer",
    "Authorization Response Code": "string",
    "Approved/Declined": "string",
    "POS Entry Mode": "string",
    "Merchant Category Code (MCC)": "string",
    "Merchant Name": "string",
    "Merchant Location": "string",
    "Card Acceptor Country Code": "string",
    "Acquirer Country Code": "string",
    "MOTO/ECI/Recurring": "string",
    "Issuer Currency Code": "string",
    "Retrieval Reference Number": "string",
    "Transaction ID": "string",
    "Statused By User ID": "string",
    "Agent Name": "string",
    "Alert Status change Timestamp (Asia/Calcutta)": "datetime",
    "Action taken or status": "string",
    "Rule type": "string",
    "Rule Name": "string"
}'::text WHERE
idashboardresultsetid = 33;


UPDATE ui.dashboardquery SET
vcdashboardquery = '{
    "All" :{
      "ClosedOn":"select accountid.long_ as \"Account ID\", null as \"Document Number\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) =''array'' then cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''txn''->''attribs''->''pismo_raw''->''fields''->>''last_four_digits'' else  cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''txn''->''attribs''->''pismo_raw''->''fields''->>''last_four_digits'' END  as \"Last 4 digits of card\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) =''array'' then cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''observations''->''payerVPA''->>''vpaName'' else  cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''observations''->''payerVPA''->>''vpaName'' END  as \"Customer Name\", TransactionAmount.double_ / 100 as \"Transaction Amount\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) =''array'' then cast(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''txn''->>''ts'' as timestamp) at time zone ''Asia/Kolkata'' at time zone  :timeZone else cast(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''txn''->>''ts'' as timestamp) at time zone ''Asia/Kolkata'' at time zone  :timeZone END  as \"Authorization Timestamp\", riskscore.long_ as \"Advanced Authorization Risk Score\", null as \"Authorization Response Code\", triggeredtype.text_ as \"Approved/Declined\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) =''array'' then cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''txn''->''attribs''->>''pos_entry_mode'' else cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''txn''->''attribs''->>''pos_entry_mode'' END  as \"POS Entry Mode\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) =''array'' then cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''payee''->>''mcc'' else cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''payee''->>''mcc'' END  as \"Merchant Category Code (MCC)\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) = ''array'' THEN cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''payeeVPA''->>''vpaName'' ELSE cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''observations''->''payeeVPA''->>''vpaName'' END as \"Merchant Name\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) = ''array'' THEN cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''txn''->''attribs''->''pismo_raw''->''fields''->>''merchant_state_or_country_code'' ELSE cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''txn''->''attribs''->''pismo_raw''->''fields''->>''merchant_state_or_country_code'' END as \"Merchant Location\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) = ''array'' THEN cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''txn''->''attribs''->''pismo_raw''->''fields''->>''merchant_state_or_country_code'' ELSE cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''txn''->''attribs''->''pismo_raw''->''fields''->>''merchant_state_or_country_code'' END as \"Card Acceptor Country Code\", null as \"Acquirer Country Code\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) = ''array'' THEN cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''txn''->''attribs''->>''moto_eci_recurring'' ELSE cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''txn''->''attribs''->>''moto_eci_recurring'' END as \"MOTO/ECI/Recurring\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) = ''array'' THEN cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''payer''->>''currency'' ELSE cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''payer''->>''currency'' END as \"Issuer Currency Code\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) = ''array'' THEN cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''txn''->''attribs''->''pismo_raw''->''fields''->''original_network_data''->>''f37_retrieval_reference_number'' ELSE cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''txn''->''attribs''->''pismo_raw''->''fields''->''original_network_data''->>''f37_retrieval_reference_number'' END as \"Retrieval Reference Number\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) = ''array'' THEN cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''txn''->>''id'' ELSE cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''txn''->>''id'' END as \"Transaction ID\", CASE WHEN  closedby.user_id_ is not null THEN closedby.user_id_ ELSE ''Auto Closed'' END as \"Statused By User ID\", CASE WHEN  closedby.user_id_ is not null THEN userinfo.first_ ||'' '' || userinfo.last_ ELSE ''Auto Closed'' END as \"Agent Name\", hiproinst.end_time_  as  \"Alert Status change Timestamp (Asia/Calcutta)\", CASE when actionvar.text_ = ''Value_Update_Whitelist'' THEN ''Update Whitelist'' when actionvar.text_ = ''Value_Fraud'' THEN ''Report Fraud to CRM'' when actionvar.text_ = ''Value_Close'' THEN ''False Positive, Close Case'' END as \"Action taken or status\", triggeredtype.text_ as \"Rule type\", replace(replace(replace(rulename.text_, ''['', ''''), '']'',''''),''\"'','''') as \"Rule Name\" from camunda.act_hi_procinst hiproinst full outer join camunda.act_hi_varinst actionvar on actionvar.proc_inst_id_ = hiproinst.proc_inst_id_ and actionvar.name_ = ''Action'' full outer join camunda.act_hi_op_log closedby on closedby.id_ = (select id_ from camunda.act_hi_op_log where proc_inst_id_ = hiproinst.proc_inst_id_ and operation_type_ = ''Complete'' and entity_type_ = ''Task'' and property_ = ''delete'' order by timestamp_ desc limit 1) full outer join camunda.act_hi_varinst accountid on accountid.proc_inst_id_ = hiproinst.proc_inst_id_ and accountid.name_ = ''accountid'' full outer join camunda.act_hi_varinst riskscore on riskscore.proc_inst_id_ = hiproinst.proc_inst_id_ and riskscore.name_ = ''RiskScore'' full outer join camunda.act_hi_varinst  TransactionAmount on TransactionAmount.proc_inst_id_ = hiproinst.proc_inst_id_ and TransactionAmount.name_ = ''TransactionAmount'' full outer join camunda.act_hi_varinst triggeredtype  on triggeredtype.proc_inst_id_ = hiproinst.proc_inst_id_ and triggeredtype.name_ = ''triggeredtype'' full outer join camunda.act_hi_varinst  Txn on Txn.proc_inst_id_ = hiproinst.proc_inst_id_ and Txn.name_ = ''Transaction'' full outer join camunda.act_ge_bytearray Txnorg on Txnorg.id_ = Txn.bytearray_id_ full outer join camunda.act_hi_varinst rulename on rulename.proc_inst_id_ = hiproinst.proc_inst_id_ and rulename.name_ = ''failedRules'' full outer join camunda.act_id_user userinfo on userinfo.id_ = closedby.user_id_ where cast(hiproinst.end_time_ as date) between cast(:StartDate as date) and cast(:EndDate as date)-1 and hiproinst.state_ = ''COMPLETED'' and hiproinst.proc_def_key_ not in ( ''invoice'', ''ReviewInvoice'',''Orchestrator'', ''Sanctions'')",
      "CreatedOn":"select accountid.long_ as \"Account ID\", null as \"Document Number\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) =''array'' then cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''txn''->''attribs''->''pismo_raw''->''fields''->>''last_four_digits'' else  cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''txn''->''attribs''->''pismo_raw''->''fields''->>''last_four_digits'' END  as \"Last 4 digits of card\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) =''array'' then cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''observations''->''payerVPA''->>''vpaName'' else  cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''observations''->''payerVPA''->>''vpaName'' END  as \"Customer Name\", TransactionAmount.double_ / 100 as \"Transaction Amount\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) =''array'' then cast(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''txn''->>''ts'' as timestamp) at time zone ''Asia/Kolkata'' at time zone  :timeZone else cast(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''txn''->>''ts'' as timestamp) at time zone ''Asia/Kolkata'' at time zone  :timeZone END  as \"Authorization Timestamp\", riskscore.long_ as \"Advanced Authorization Risk Score\", null as \"Authorization Response Code\", triggeredtype.text_ as \"Approved/Declined\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) =''array'' then cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''txn''->''attribs''->>''pos_entry_mode'' else cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''txn''->''attribs''->>''pos_entry_mode'' END  as \"POS Entry Mode\", CASE WHEN jsonb_typeof(cast(encode(Txnorg.bytes_, ''escape'') as jsonb)) =''array'' then cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->0->''payee''->>''mcc'' else cast(encode(Txnorg.bytes_, ''escape'') as jsonb)->''payee''->>''mcc'' END  as \"Merchant Category Code (MCC)\", CASE WHEN json